  `machinery_brand` varchar(255) DEFAULT NULL COMMENT '品牌',
  `machinery_spec` varchar(255) DEFAULT NULL COMMENT '规格型号',
  `machinery_type_id` bigint(20) NOT NULL COMMENT '设备类型ID',
  `machinery_type_code` varchar(64) DEFAULT NULL COMMENT '设备类型编码',
  `machinery_type_name` varchar(255) DEFAULT NULL COMMENT '设备类型名称',
  `location` varchar(255) DEFAULT NULL COMMENT '位置',
  `workshop_id` bigint(20) NOT NULL COMMENT '所属车间ID',
  `workshop_code` varchar(64) DEFAULT '' COMMENT '所属车间编码',
  `workshop_name` varchar(255) DEFAULT NULL COMMENT '所属车间名称',
  `status` varchar(64) DEFAULT NULL COMMENT '设备状态',
  `remark` varchar(255) DEFAULT '' COMMENT '备注',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户id',
  `capacity` varchar(255) DEFAULT NULL COMMENT '产能',
  `pcl_model` varchar(255) DEFAULT NULL COMMENT 'PCL型号',
  `purchasing_time` datetime DEFAULT NULL COMMENT '购买日期',
  `assign_user` varchar(255) DEFAULT NULL COMMENT '分配用户',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=412 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='设备表';

