-- ----------------------------
-- Table structure for order_outbound
-- ----------------------------
DROP TABLE IF EXISTS `order_outbound`;
CREATE TABLE `order_outbound` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '出库id',
  `external_id` varchar(64) DEFAULT NULL COMMENT '外部系统id',
  `number` varchar(64) DEFAULT NULL COMMENT '出库单编号',
  `outbound_total_price` double(14,3) DEFAULT 0.000 COMMENT '出库总价',
  `status` varchar(64) DEFAULT NULL COMMENT '状态',
  `no_send` double(14,3) DEFAULT 0.000 COMMENT '未发',
  `send_out` double(14,3) DEFAULT 0.000 COMMENT '已发',
  `source` varchar(100) DEFAULT NULL COMMENT '来源',
  `remark` varchar(100) DEFAULT NULL COMMENT '备注',
  `sale_total_price` double(14,3) DEFAULT 0.000 COMMENT '销售总价',
  `total_weight` varchar(64) DEFAULT NULL COMMENT '总净重',
  `total_price` double(14,3) DEFAULT 0.000 COMMENT '总价',
  `customer_number` varchar(64) DEFAULT NULL COMMENT '客户编号',
  `customer_name` varchar(64) DEFAULT NULL COMMENT '客户名称',
  `customer_order_number` varchar(64) DEFAULT NULL COMMENT '客户订单号',
  `delivery_date` varchar(64) DEFAULT NULL COMMENT '交货日期',
  `is_tax` varchar(64) DEFAULT NULL COMMENT '是否含税',
  `quantity` double(14,3) DEFAULT 0.000 COMMENT '数量',
  `order_date` varchar(64) DEFAULT NULL COMMENT '订单日期',
  `pieces` varchar(64) DEFAULT NULL COMMENT '总件数',
  `sale_number` varchar(64) DEFAULT NULL COMMENT '销售单号',
  `is_sales` varchar(64) DEFAULT NULL COMMENT '0代表选择的是销售单出库   1 代表选择的是无销售单出库',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=400 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='销售订单模块-PC扫码出库表\r\n';

