DROP TABLE IF EXISTS `order_po`;
CREATE TABLE `order_po` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '采购订单id',
  `external_id` varchar(64) DEFAULT NULL COMMENT '外部系统id',
