  `status` varchar(100) DEFAULT NULL COMMENT '类型\r\n',
  `state` varchar(10) DEFAULT '0' COMMENT '状态\n0:未到货\n1:部分到货\n2:全部到货',
  `is_tax` varchar(64) DEFAULT NULL COMMENT '是否含税',
  `remark` varchar(64) DEFAULT NULL COMMENT '备注',
  `product_type` varchar(64) DEFAULT NULL COMMENT '产品类别',
