  `total_price` decimal(10,0) DEFAULT NULL COMMENT '总价',
  `color` varchar(64) DEFAULT NULL COMMENT '颜色',
  `box_number` varchar(64) DEFAULT NULL COMMENT '箱号',
  `axles_number` varchar(64) DEFAULT NULL COMMENT '轴数',
  `batch` varchar(100) DEFAULT NULL COMMENT '批次',
  `bar_code` varchar(64) DEFAULT NULL COMMENT '条码',
  `remark` varchar(100) DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='退货明细表';

-- ----------------------------
-- Records of order_return_item
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for order_sale
-- ----------------------------
DROP TABLE IF EXISTS `order_sale`;
CREATE TABLE `order_sale` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '销售订单id',
  `number` varchar(64) DEFAULT NULL COMMENT '销售单编号',
  `customer_number` varchar(64) DEFAULT NULL COMMENT '客户编号',
  `customer_name` varchar(64) DEFAULT NULL COMMENT '客户名称',
  `customer_order_number` varchar(64) DEFAULT NULL COMMENT '客户订单号',
  `address` varchar(64) DEFAULT NULL COMMENT '收货地址',
  `remark` varchar(64) DEFAULT NULL COMMENT '备注',
  `order_date` varchar(64) DEFAULT NULL COMMENT '订货日期',
  `is_tax` varchar(64) DEFAULT NULL COMMENT '是否含税',
  `include_tax` double(14,4) DEFAULT 0.0000 COMMENT '含税',
  `delivery_date` varchar(64) DEFAULT NULL COMMENT '交货日期',
  `quantity` double(14,2) DEFAULT 0.00 COMMENT '总数量',
  `no_include_tax` double(14,4) DEFAULT 0.0000 COMMENT '不含税',
  `price_mode` varchar(64) DEFAULT NULL COMMENT '价格模式',
  `copper_price` varchar(64) DEFAULT NULL COMMENT '铜价',
  `copper_price_two` varchar(64) DEFAULT NULL COMMENT '铜价2',
  `aluminium_price` varchar(64) DEFAULT NULL COMMENT '铝价',
  `aluminium_price_two` varchar(64) DEFAULT NULL COMMENT '铝价2',
  `price_model` varchar(64) DEFAULT NULL COMMENT '重量还是件数',
  `status` varchar(64) DEFAULT NULL COMMENT '状态',
  `copper_tax_rate` double(14,2) DEFAULT 0.00 COMMENT '铜价税率',
  `aluminium_tax_rate` double(14,2) DEFAULT 0.00 COMMENT '铝价税率',
  `external_id` varchar(64) DEFAULT NULL COMMENT '外部系统id',
  `create_time` datetime DEFAULT current_timestamp() COMMENT '创建时间',
  `update_time` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `creator` varchar(255) DEFAULT NULL COMMENT '创建者',
  `updater` varchar(255) DEFAULT NULL COMMENT '更新者',
  `deleted` bit(1) DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) DEFAULT 1 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `sale_number` (`number`)
) ENGINE=InnoDB AUTO_INCREMENT=484 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='销售订单表';

-- ----------------------------
-- Records of order_sale
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for order_sale_item
-- ----------------------------
DROP TABLE IF EXISTS `order_sale_item`;
CREATE TABLE `order_sale_item` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '明细id',
  `number` varchar(64) DEFAULT NULL COMMENT '销售单明细编号',
  `sale_number` varchar(64) DEFAULT NULL COMMENT '销售订单编号',
  `product_number` varchar(64) DEFAULT NULL COMMENT '产品编号',
  `line_type` varchar(64) DEFAULT NULL COMMENT '线别',
  `model` varchar(64) DEFAULT NULL COMMENT '型号',
  `spec` varchar(64) DEFAULT NULL COMMENT '规格',
  `quantity` double(14,2) DEFAULT 0.00 COMMENT '数量',
  `unit` varchar(64) DEFAULT NULL COMMENT '单位',
  `raw_price` double(14,4) DEFAULT 0.0000 COMMENT '原材料价',
  `processing_fee` double(14,4) DEFAULT 0.0000 COMMENT '加工费',
  `price` varchar(64) DEFAULT NULL COMMENT '单价',
  `status` varchar(64) DEFAULT '未完成' COMMENT '状态(此状态代表当前这个销售明细是否已经加入到出库当中)',
  `outbound_status` varchar(64) DEFAULT '0' COMMENT '出库状态(此状态代表当前这个销售明细是否在出库单当中已经出库完成，涉及销售单状态是否改变成完成)0代表出库未完成，1代表出库已完成',
  `stocks` double(14,2) DEFAULT 0.00 COMMENT '库存',
  `total_price` double(14,4) DEFAULT 0.0000 COMMENT '总价',
  `discount` double(14,0) DEFAULT 0 COMMENT '折扣',
  `color` varchar(64) DEFAULT NULL COMMENT '颜色',
  `panhao` varchar(64) DEFAULT NULL COMMENT '盘号',
  `customer_code` varchar(64) DEFAULT NULL COMMENT '客户代码',
  `inventory_number` varchar(64) DEFAULT NULL COMMENT '存货编号',
  `warrant_number` varchar(64) DEFAULT NULL COMMENT '制令单号',
  `spec_price` varchar(64) DEFAULT NULL COMMENT '规格价格',
  `remark` varchar(64) DEFAULT NULL COMMENT '备注',
  `sale_item_number` varchar(64) DEFAULT NULL COMMENT '销售单明细编号',
  `create_time` datetime DEFAULT current_timestamp() COMMENT '创建时间',
  `update_time` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `creator` varchar(255) DEFAULT NULL COMMENT '创建者',
  `updater` varchar(255) DEFAULT NULL COMMENT '更新者',
  `deleted` bit(1) DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) DEFAULT 1 COMMENT '租户编号',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1293 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------
-- Records of order_sale_item
-- ----------------------------
