-- Records of pay_notify_task
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for pay_order
-- ----------------------------
DROP TABLE IF EXISTS `pay_order`;
CREATE TABLE `pay_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '支付订单编号',
  `merchant_id` bigint(20) NOT NULL COMMENT '商户编号',
  `app_id` bigint(20) NOT NULL COMMENT '应用编号',
  `channel_id` bigint(20) DEFAULT NULL COMMENT '渠道编号',
  `channel_code` varchar(32) DEFAULT NULL COMMENT '渠道编码',
  `merchant_order_id` varchar(64) NOT NULL COMMENT '商户订单编号',
  `subject` varchar(32) NOT NULL COMMENT '商品标题',
  `body` varchar(128) NOT NULL COMMENT '商品描述',
  `notify_url` varchar(1024) NOT NULL COMMENT '异步通知地址',
  `notify_status` tinyint(4) NOT NULL COMMENT '通知商户支付结果的回调状态',
  `amount` bigint(20) NOT NULL COMMENT '支付金额，单位：分',
  `channel_fee_rate` double DEFAULT 0 COMMENT '渠道手续费，单位：百分比',
  `channel_fee_amount` bigint(20) DEFAULT 0 COMMENT '渠道手续金额，单位：分',
  `status` tinyint(4) NOT NULL COMMENT '支付状态',
  `user_ip` varchar(50) NOT NULL COMMENT '用户 IP',
  `expire_time` datetime NOT NULL DEFAULT current_timestamp() COMMENT '订单失效时间',
  `success_time` datetime DEFAULT current_timestamp() COMMENT '订单支付成功时间',
  `notify_time` datetime DEFAULT current_timestamp() COMMENT '订单支付通知时间',
  `success_extension_id` bigint(20) DEFAULT NULL COMMENT '支付成功的订单拓展单编号',
  `refund_status` tinyint(4) NOT NULL COMMENT '退款状态',
  `refund_times` tinyint(4) NOT NULL COMMENT '退款次数',
  `refund_amount` bigint(20) NOT NULL COMMENT '退款总金额，单位：分',
  `channel_user_id` varchar(255) DEFAULT NULL COMMENT '渠道用户编号',
  `channel_order_no` varchar(64) DEFAULT NULL COMMENT '渠道订单号',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=125 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='支付订单\n';

-- ----------------------------
-- Records of pay_order
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for pay_order_extension
-- ----------------------------
DROP TABLE IF EXISTS `pay_order_extension`;
CREATE TABLE `pay_order_extension` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '支付订单编号',
  `no` varchar(64) NOT NULL COMMENT '支付订单号',
  `order_id` bigint(20) NOT NULL COMMENT '支付订单编号',
  `channel_id` bigint(20) NOT NULL COMMENT '渠道编号',
  `channel_code` varchar(32) NOT NULL COMMENT '渠道编码',
  `user_ip` varchar(50) NOT NULL COMMENT '用户 IP',
  `status` tinyint(4) NOT NULL COMMENT '支付状态',
  `channel_extras` varchar(256) DEFAULT NULL COMMENT '支付渠道的额外参数',
  `channel_notify_data` varchar(1024) DEFAULT NULL COMMENT '支付渠道异步通知的内容',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='支付订单\n';

-- ----------------------------
-- Records of pay_order_extension
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for pay_refund
-- ----------------------------
DROP TABLE IF EXISTS `pay_refund`;
CREATE TABLE `pay_refund` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '支付退款编号',
  `merchant_id` bigint(20) NOT NULL COMMENT '商户编号',
  `app_id` bigint(20) NOT NULL COMMENT '应用编号',
  `channel_id` bigint(20) NOT NULL COMMENT '渠道编号',
  `channel_code` varchar(32) NOT NULL COMMENT '渠道编码',
  `order_id` bigint(20) NOT NULL COMMENT '支付订单编号 pay_order 表id',
  `trade_no` varchar(64) NOT NULL COMMENT '交易订单号 pay_extension 表no 字段',
  `merchant_order_id` varchar(64) NOT NULL COMMENT '商户订单编号（商户系统生成）',
  `merchant_refund_no` varchar(64) NOT NULL COMMENT '商户退款订单号（商户系统生成）',
  `notify_url` varchar(1024) NOT NULL COMMENT '异步通知商户地址',
  `notify_status` tinyint(4) NOT NULL COMMENT '通知商户退款结果的回调状态',
  `status` tinyint(4) NOT NULL COMMENT '退款状态',
  `type` tinyint(4) NOT NULL COMMENT '退款类型(部分退款，全部退款)',
  `pay_amount` bigint(20) NOT NULL COMMENT '支付金额,单位分',
  `refund_amount` bigint(20) NOT NULL COMMENT '退款金额,单位分',
  `reason` varchar(256) NOT NULL COMMENT '退款原因',
  `user_ip` varchar(50) DEFAULT NULL COMMENT '用户 IP',
  `channel_order_no` varchar(64) NOT NULL COMMENT '渠道订单号，pay_order 中的channel_order_no 对应',
  `channel_refund_no` varchar(64) DEFAULT NULL COMMENT '渠道退款单号，渠道返回',
  `channel_error_code` varchar(128) DEFAULT NULL COMMENT '渠道调用报错时，错误码',
  `channel_error_msg` varchar(256) DEFAULT NULL COMMENT '渠道调用报错时，错误信息',
  `channel_extras` varchar(1024) DEFAULT NULL COMMENT '支付渠道的额外参数',
  `expire_time` datetime DEFAULT NULL COMMENT '退款失效时间',
  `success_time` datetime DEFAULT NULL COMMENT '退款成功时间',
  `notify_time` datetime DEFAULT NULL COMMENT '退款通知时间',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='退款订单';

-- ----------------------------
-- Records of pay_refund
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for plan_day
-- ----------------------------
DROP TABLE IF EXISTS `plan_day`;
CREATE TABLE `plan_day` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '日计划id',
  `number` varchar(255) NOT NULL COMMENT '编号',
  `month_number` varchar(255) NOT NULL COMMENT '月计划编号',
  `day` varchar(255) NOT NULL COMMENT '日期',
  `workshop` varchar(255) NOT NULL COMMENT '车间',
  `production_line` varchar(255) NOT NULL COMMENT '生产线',
  `mo_number` varchar(255) DEFAULT NULL COMMENT '生产订单编号',
  `product_number` varchar(255) DEFAULT NULL COMMENT '产品编号',
  `product_name` varchar(255) DEFAULT NULL COMMENT '产品名称',
  `plan_qty` double NOT NULL COMMENT '计划数量',
  `unit` varchar(255) NOT NULL COMMENT '单位',
  `creator` varchar(255) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(255) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `number` (`number`),
  KEY `month_number` (`month_number`),
  CONSTRAINT `plan_day_ibfk_1` FOREIGN KEY (`month_number`) REFERENCES `plan_month` (`number`)
