  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `process_id` bigint(20) NOT NULL COMMENT '工序ID',
  `process_code` varchar(255) DEFAULT NULL COMMENT '工序编码',
  `process_name` varchar(255) DEFAULT NULL COMMENT '工序名称',
  `equipment_code` varchar(255) DEFAULT NULL COMMENT '设备编号',
  `finished_time` datetime DEFAULT NULL COMMENT '完工时间',
  `pause_time` varchar(255) DEFAULT NULL COMMENT '暂停时间',
  `pause_reason` varchar(255) DEFAULT NULL COMMENT '暂停原因',
  `order_quantity` double(14,2) DEFAULT 1.00 COMMENT '排产数量',
  `work_order_quentity` double(14,2) DEFAULT 1.00 COMMENT '订单数量',
  `reporting_progress` double(14,2) DEFAULT 0.00 COMMENT '报工进度',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1993 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='生产报工记录表';

