-- Table structure for qc_other_record
-- ----------------------------
DROP TABLE IF EXISTS `qc_other_record`;
CREATE TABLE `qc_other_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '其他检验单id',
  `number` varchar(64) DEFAULT NULL COMMENT '其他检验单编号',
  `work_order_code` varchar(64) DEFAULT NULL COMMENT '生产订单编号',
  `other_standard_number` varchar(64) DEFAULT NULL COMMENT '检验标准编号',
  `item_code` varchar(64) DEFAULT NULL COMMENT '产品编号',
  `item_name` varchar(255) DEFAULT NULL COMMENT '产品名称',
  `client_code` varchar(64) DEFAULT NULL COMMENT '客户编码',
  `client_name` varchar(255) DEFAULT NULL COMMENT '客户名称',
  `model` varchar(64) DEFAULT NULL COMMENT '型号',
  `spec` varchar(64) DEFAULT NULL COMMENT '规格',
  `line_type` varchar(64) DEFAULT NULL COMMENT '线别',
  `reel_number` varchar(64) DEFAULT NULL COMMENT '盘号',
  `color` varchar(64) DEFAULT NULL COMMENT '颜色',
  `kind` varchar(64) DEFAULT NULL COMMENT '类别',
  `unit_of_measure` varchar(64) DEFAULT NULL COMMENT '单位',
  `purchase_price` double(14,2) DEFAULT NULL COMMENT '采购价',
  `quantity` double(14,0) DEFAULT NULL COMMENT '数量',
  `includ_tax` double(14,2) DEFAULT NULL COMMENT '含税总价',
  `no_includ_tax` double(14,2) DEFAULT NULL COMMENT '不含税总价',
  `vendor` varchar(64) DEFAULT NULL COMMENT '供应商',
  `check_number` varchar(64) DEFAULT NULL COMMENT '抽检数',
  `inspect_way` varchar(255) DEFAULT NULL COMMENT '检验方式',
  `version` varchar(64) DEFAULT NULL COMMENT '版本',
  `status` varchar(64) DEFAULT NULL COMMENT '状态\r\n0：不合格\r\n1：合格',
  `inspect_flag` varchar(10) DEFAULT NULL COMMENT '是否有检验项目\r\n0：否\r\n1：是',
  `inspect_group` varchar(255) DEFAULT NULL COMMENT '质检组',
  `inspect_user` varchar(255) DEFAULT NULL COMMENT '质检员',
  `inspect_start_time` datetime DEFAULT NULL COMMENT '检验开始时间',
  `inspect_end_time` datetime DEFAULT NULL COMMENT '检验结束时间',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT current_timestamp() COMMENT '创建时间',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='其他检验单表';

