CREATE TABLE `qc_other_standard` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自制标准id',
  `number` varchar(255) DEFAULT NULL COMMENT '检验编号',
  `name` varchar(64) DEFAULT NULL COMMENT '检验名称',
  `method` varchar(64) DEFAULT NULL COMMENT '检验方式',
  `product_type` varchar(255) DEFAULT NULL COMMENT '产品分类',
  `model` varchar(255) DEFAULT NULL COMMENT '型号',
  `spec` varchar(255) DEFAULT NULL COMMENT '规格',
  `line_type` varchar(255) DEFAULT NULL COMMENT '线别',
  `reel_number` varchar(255) DEFAULT NULL COMMENT '盘号',
  `color` varchar(255) DEFAULT NULL COMMENT '颜色',
  `item_code` varchar(64) DEFAULT NULL COMMENT '产品编号',
