  `number` varchar(64) DEFAULT NULL COMMENT '到货通知单编号',
  `receipt_number` varchar(255) DEFAULT NULL COMMENT '采购单编号',
  `currency` varchar(64) DEFAULT NULL COMMENT '币种',
  `address` varchar(64) DEFAULT NULL COMMENT '收货地址',
