-- ----------------------------
-- Procedure structure for GetItemsByCustomerName
-- ----------------------------
DROP PROCEDURE IF EXISTS `GetItemsByCustomerName`;
delimiter ;;
CREATE PROCEDURE `GetItemsByCustomerName`(IN customer_name VARCHAR(100))
BEGIN

    SELECT
        md_item.item_code,
        md_item.item_name,
        md_item.line_type,
        md_item.model,
        md_item.spec,
        md_item.unit_of_measure,
        md_item.purchase_price,
        md_item.sale_price,
        md_item.item_type_name,
        customer_name AS customer_name
    FROM md_item
    JOIN (

        SELECT
            SUBSTRING_INDEX(SUBSTRING_INDEX(order_quotes.model, ',', numbers.n), ',', -1) AS model
        FROM
            order_quotes

        JOIN (
            SELECT 1 AS n UNION ALL
            SELECT 2 AS n UNION ALL
            SELECT 3 AS n UNION ALL
            SELECT 4 AS n
        ) numbers ON CHAR_LENGTH(order_quotes.model) - CHAR_LENGTH(REPLACE(order_quotes.model, ',', '')) >= numbers.n - 1
        WHERE
            order_quotes.customer_name = customer_name
    ) AS temp_models ON md_item.model = temp_models.model;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for proc_add_field
-- ----------------------------
DROP PROCEDURE IF EXISTS `proc_add_field`;
delimiter ;;
CREATE PROCEDURE `proc_add_field`()
BEGIN

DECLARE end_flag int DEFAULT 0;

DECLARE my_table_name VARCHAR(100);

DECLARE album_curosr CURSOR FOR

          SELECT DISTINCT table_name FROM
          information_schema.columns
          WHERE
          table_schema = 'mes-pro'
          AND table_name LIKE 'md_%'
          AND table_name NOT IN (SELECT table_name FROM
          information_schema.columns
          WHERE table_schema = 'mes-pro'
          AND table_name LIKE 'md_%'
          AND column_name = 'creator'
					AND column_name = 'create_time'
					AND column_name = 'updater'
					AND column_name = 'update_time'
					AND column_name = 'deleted'
					AND column_name = 'tenant_id');



DECLARE CONTINUE HANDLER FOR NOT FOUND SET end_flag=1;

OPEN album_curosr;

REPEAT

FETCH album_curosr INTO my_table_name;


SET @stmt = CONCAT("ALTER TABLE ",my_table_name ," ADD COLUMN `creator` varchar(64) DEFAULT '' COMMENT '创建者'");

prepare stmt FROM @stmt;

EXECUTE  stmt;

SELECT @stmt;

DEALLOCATE PREPARE stmt;

UNTIL end_flag END REPEAT;

close album_curosr;

END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
